(3867505, 547478, 45377, '<td valign="top">Good colours, Interesting sky. Would like to see the whole shot in focus and the tilted horizon fixed. Good composition</td>', 'Good colours, Interesting sky. Would like to see the whole shot in focus and the tilted horizon fixed. Good composition', '2007-07-04 13:14:50.000000', NULL, 1),
(3867519, 545317, 53094, '<td valign="top">Very nice wide angle shot.  Without the pier, this wouldn''t be that interesting...the pier makes the shot.  Good composition.</td>', 'Very nice wide angle shot.  Without the pier, this wouldn''t be that interesting...the pier makes the shot.  Good composition.', '2007-07-04 13:17:20.000000', NULL, 1),
(3867535, 547281, 45377, '<td valign="top">Dramatic shot. A tad too much noise, perhaps try running it through neat image.</td>', 'Dramatic shot. A tad too much noise, perhaps try running it through neat image.', '2007-07-04 13:20:30.000000', NULL, 1),
(3867540, 546661, 45377, '<td valign="top">Wow! We don''t have these in Scarborough (England) - wish we did.</td>', 'Wow! We don''t have these in Scarborough (England) - wish we did.', '2007-07-04 13:21:45.000000', NULL, 1),
(3867548, 547866, 53094, '<td valign="top">Nice soft colors, and I like the jetty.  The horizon could be a little straighter, and maybe not quite so centered.</td>', 'Nice soft colors, and I like the jetty.  The horizon could be a little straighter, and maybe not quite so centered.', '2007-07-04 13:23:10.000000', NULL, 1),
(3867555, 546660, 53094, '<td valign="top">Great clouds, and I like the person and bird.  On my monitor the contrast looks a little high.  I think it might look better softened just a tad.</td>', 'Great clouds, and I like the person and bird.  On my monitor the contrast looks a little high.  I think it might look better softened just a tad.', '2007-07-04 13:25:26.000000', NULL, 1),
