(3867604, 545928, 15711, '<td valign="top">Lovely!!!!</td>', 'Lovely!!!!', '2007-07-04 13:33:37.000000', NULL, 1),
(3867605, 547238, 53094, '<td valign="top">Beautiful!  So far, one of my favorites in the challenge.</td>', 'Beautiful!  So far, one of my favorites in the challenge.', '2007-07-04 13:33:40.000000', NULL, 1),
(3867609, 546368, 15711, '<td valign="top">I like the three distinct "layers": sea, boats, clouds.</td>', 'I like the three distinct "layers": sea, boats, clouds.', '2007-07-04 13:34:02.000000', NULL, 1),
(3867625, 547917, 15711, '<td valign="top">That looks like a lake to me, but I love the sat of red and the composition with the steps and the flip flops. No points off cause it might be an ocean setting I''ve never seen.  Here, it''s sand and waves. LOL 8</td>', 'That looks like a lake to me, but I love the sat of red and the composition with the steps and the flip flops. No points off cause it might be an ocean setting I''ve never seen.  Here, it''s sand and waves. LOL 8', '2007-07-04 13:37:16.000000', NULL, 1),
(3867640, 547404, 53094, '<td valign="top">Great colors, and love the rough water.  The bottom of this photo is a little distracting, in my opinion.</td>', 'Great colors, and love the rough water.  The bottom of this photo is a little distracting, in my opinion.', '2007-07-04 13:40:55.000000', NULL, 1),
(3867649, 547443, 15711, '<td valign="top">What a pretty setting.  So funny, I''ve never seen a rocky coast like that.  In Texas it''s sand or nothing. LOL  Very nicely composed.</td>', 'What a pretty setting.  So funny, I''ve never seen a rocky coast like that.  In Texas it''s sand or nothing. LOL  Very nicely composed.', '2007-07-04 13:42:39.000000', NULL, 1),
(3867652, 547351, 15711, '<td valign="top">I thought it said sea.   Hmmmmmmmm</td>', 'I thought it said sea.   Hmmmmmmmm', '2007-07-04 13:43:31.000000', NULL, 1),
(3867655, 545239, 15711, '<td valign="top">Great balance!! Excellent focus too.</td>', 'Great balance!! Excellent focus too.', '2007-07-04 13:44:29.000000', NULL, 1),
(3867657, 547986, 15711, '<td valign="top">WOAH - perfect tones and intense texture.  Fantastic.</td>', 'WOAH - perfect tones and intense texture.  Fantastic.', '2007-07-04 13:45:18.000000', NULL, 1),
(3867658, 548050, 53094, '<td valign="top">The reflection of the sky in the water is beautiful, and the colors are outstanding.  The sailboats add interest.  Nice photo.</td>', 'The reflection of the sky in the water is beautiful, and the colors are outstanding.  The sailboats add interest.  Nice photo.', '2007-07-04 13:45:38.000000', NULL, 1),
(3867659, 546868, 15711, '<td valign="top">That looks like a lake to me.  Didn''t the challenge say sea???? Maybe I''m being too critical.</td>', 'That looks like a lake to me.  Didn''t the challenge say sea???? Maybe I''m being too critical.', '2007-07-04 13:45:48.000000', NULL, 1),
