(3867810, 547891, 34659, '<td valign="top">I love this.  The blues &amp; greens of the ocean and the wave action really make this shot.</td>', 'I love this.  The blues & greens of the ocean and the wave action really make this shot.', '2007-07-04 14:21:07.000000', NULL, 1),
(3867812, 547238, 34659, '<td valign="top">Great tones &amp; composition.  A little too much NI for my personal taste, but a 9 nonetheless.</td>', 'Great tones & composition.  A little too much NI for my personal taste, but a 9 nonetheless.', '2007-07-04 14:21:40.000000', NULL, 1),
