(3867857, 545897, 74559, '<td valign="top">This is really lovely! Love the deep rich blue and the Moon reflection on the water. Wonderful how the clouds are lit by the Moon, and you even caught a lunar halo!</td>', 'This is really lovely! Love the deep rich blue and the Moon reflection on the water. Wonderful how the clouds are lit by the Moon, and you even caught a lunar halo!', '2007-07-04 14:33:31.000000', NULL, 1),
(3867863, 546357, 7786, '<td valign="top">Interesting. Odd to see one wave go diognally to the other waves! Placing the stone less centrally would make a better composition.</td>', 'Interesting. Odd to see one wave go diognally to the other waves! Placing the stone less centrally would make a better composition.', '2007-07-04 14:35:16.000000', NULL, 1),
(3867890, 545928, 5015, '<td valign="top">I might have liked it more in color</td>', 'I might have liked it more in color', '2007-07-04 14:41:47.000000', NULL, 1),
(3867956, 547352, 45377, '<td valign="top">Great shot. Good exposure, sharp focus, my eye is drawn up the hill. Seascape?</td>', 'Great shot. Good exposure, sharp focus, my eye is drawn up the hill. Seascape?', '2007-07-04 15:00:59.000000', NULL, 1),
