(3868054, 546264, 44611, '<td valign="top">Great shot of the sea - in spite of having minimal subject matter this comes across as really interesting.</td>', 'Great shot of the sea - in spite of having minimal subject matter this comes across as really interesting.', '2007-07-04 15:44:14.000000', NULL, 1),
