(3869340, 545317, 63267, '<td valign="top">That sun sure is large in the mornings like this.  But it also overpowered the image and made the exposure suffer. 5</td>', 'That sun sure is large in the mornings like this.  But it also overpowered the image and made the exposure suffer. 5', '2007-07-04 22:12:01.000000', NULL, 1);
