(3871142, 545928, 72916, '<td valign="top">I like the picture, but the ocean seems a little dark.</td>', 'I like the picture, but the ocean seems a little dark.', '2007-07-05 12:34:45.000000', NULL, 1),
(3871146, 547970, 72916, '<td valign="top">Great subject. The picture seems a little out of focus, but nice work.</td>', 'Great subject. The picture seems a little out of focus, but nice work.', '2007-07-05 12:35:41.000000', NULL, 1),
(3871148, 545317, 57260, '<td valign="top">I like the composition and I think the blown out sun is a bit too much. Would''ve opted for more of a sillouette of the dock and a less exposed sky. I feel if you stopped down a bit and used a smaller aperture you would get a better result and you''d also get a natural starburst effect from the sun making it more interesting in stead of this large white void in the centre. Also could use a little bit of sharpening.</td>', 'I like the composition and I think the blown out sun is a bit too much. Would''ve opted for more of a sillouette of the dock and a less exposed sky. I feel if you stopped down a bit and used a smaller aperture you would get a better result and you''d also get a natural starburst effect from the sun making it more interesting in stead of this large white void in the centre. Also could use a little bit of sharpening.', '2007-07-05 12:35:58.000000', NULL, 1),
(3871149, 547700, 72916, '<td valign="top">Wow. I love the colors and the reflection is amazing. Great job.</td>', 'Wow. I love the colors and the reflection is amazing. Great job.', '2007-07-05 12:37:16.000000', NULL, 1),
