(3872369, 548110, 77192, '<td valign="top">not as sharp as I''d like, but I like the moody skies :-)</td>', 'not as sharp as I''d like, but I like the moody skies :-)', '2007-07-05 17:29:04.000000', NULL, 1),
(3872371, 546661, 62727, '<td valign="top">Fantastic capture!  Resurrection Bay? 10</td>', 'Fantastic capture!  Resurrection Bay? 10', '2007-07-05 17:29:36.000000', NULL, 1),
(3872376, 545897, 62727, '<td valign="top">Stunning!  Love the soft feel and moonlight reflection on the water. 10</td>', 'Stunning!  Love the soft feel and moonlight reflection on the water. 10', '2007-07-05 17:30:24.000000', NULL, 1),
