(3872421, 548106, 42100, '<td valign="top">Beautiful moonlight and reflection...but the composition awfully static with not much happening on either side of the moon and reflection.</td>', 'Beautiful moonlight and reflection...but the composition awfully static with not much happening on either side of the moon and reflection.', '2007-07-05 17:41:49.000000', NULL, 1),
(3872428, 547300, 42100, '<td valign="top">This seem like it could be quite interesting but the foreground is very dark and it''s difficult to tell what''s going there.</td>', 'This seem like it could be quite interesting but the foreground is very dark and it''s difficult to tell what''s going there.', '2007-07-05 17:44:29.000000', NULL, 1),
