(3875035, 547901, 74017, '<td valign="top">love this shot  capturing the rays of sun light makes it that much more spectacular</td>', 'love this shot  capturing the rays of sun light makes it that much more spectacular', '2007-07-06 10:19:40.000000', NULL, 1),
