(3882344, 545203, 67553, '<td valign="top">Beautiful capture!  This is a very serene image, and I love the colors.  Not oversaturated like I would tend to do.  :)</td>', 'Beautiful capture!  This is a very serene image, and I love the colors.  Not oversaturated like I would tend to do.  :)', '2007-07-08 16:14:25.000000', NULL, 1),
(3882349, 547910, 67553, '<td valign="top">Great shot.  I like the concentric circles and the beautiful blue of the sky reflected in the water.  He looks a little unhappy, though!  :)</td>', 'Great shot.  I like the concentric circles and the beautiful blue of the sky reflected in the water.  He looks a little unhappy, though!  :)', '2007-07-08 16:17:07.000000', NULL, 1),
(3882361, 547958, 67553, '<td valign="top">The B&amp;W works well for this.  I like the sailboat way out there in the water, too.  It gives a great sense of scale.</td>', 'The B&W works well for this.  I like the sailboat way out there in the water, too.  It gives a great sense of scale.', '2007-07-08 16:20:38.000000', NULL, 1),
(3882369, 547797, 67553, '<td valign="top">Wonderful colors. I like the contrast of the sky/water with the sand, but there does not seem to be a strong focal point in this.</td>', 'Wonderful colors. I like the contrast of the sky/water with the sand, but there does not seem to be a strong focal point in this.', '2007-07-08 16:21:59.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3882375, 547551, 67553, '<td valign="top">Nice sunrise, and I like the silhouette of the land.</td>', 'Nice sunrise, and I like the silhouette of the land.', '2007-07-08 16:23:49.000000', NULL, 1),
(3882378, 547700, 67553, '<td valign="top">Absolutely beautiful.  Great job capturing the reflections!</td>', 'Absolutely beautiful.  Great job capturing the reflections!', '2007-07-08 16:25:55.000000', NULL, 1),
(3882380, 548035, 74979, '<td valign="top">powerful image, the churn of the chop</td>', 'powerful image, the churn of the chop', '2007-07-08 16:26:57.000000', NULL, 1),
(3882382, 546264, 67553, '<td valign="top">I like the composition as it''s very symmetrical.  The colors are a bit toned down, though.</td>', 'I like the composition as it''s very symmetrical.  The colors are a bit toned down, though.', '2007-07-08 16:27:12.000000', NULL, 1),
(3882387, 545212, 74979, '<td valign="top">crystal clear &amp; nice use of the rock as a frame</td>', 'crystal clear & nice use of the rock as a frame', '2007-07-08 16:28:04.000000', NULL, 1),
(3882389, 547243, 74979, '<td valign="top">serene scene...feels like summer!</td>', 'serene scene...feels like summer!', '2007-07-08 16:28:32.000000', NULL, 1),
(3882397, 546336, 74979, '<td valign="top">nice use of the diagonal on the rock formation to lead us to the sun &amp; the glorious rays above the clouds; I don''t think the person is needed..</td>', 'nice use of the diagonal on the rock formation to lead us to the sun & the glorious rays above the clouds; I don''t think the person is needed..', '2007-07-08 16:30:02.000000', NULL, 1),
(3882401, 547756, 67553, '<td valign="top">Great concept, and I like the long exposure.</td>', 'Great concept, and I like the long exposure.', '2007-07-08 16:31:03.000000', NULL, 1),
(3882403, 548110, 74979, '<td valign="top">nice contrast, the water &amp; the shoreline, the clouds against the sky &amp; the water..</td>', 'nice contrast, the water & the shoreline, the clouds against the sky & the water..', '2007-07-08 16:31:10.000000', NULL, 1),
(3882408, 547443, 74979, '<td valign="top">nice how the clouds and the rocks lead to the same place in the frame but from opposite perspectives!</td>', 'nice how the clouds and the rocks lead to the same place in the frame but from opposite perspectives!', '2007-07-08 16:31:58.000000', NULL, 1),
(3882412, 547660, 74979, '<td valign="top">serene &amp; calm...lovely tones!</td>', 'serene & calm...lovely tones!', '2007-07-08 16:32:34.000000', NULL, 1),
(3882414, 546368, 74979, '<td valign="top">interesting treatment, the clouds are fierce! the water seems like it should be darker with such a storm brewing</td>', 'interesting treatment, the clouds are fierce! the water seems like it should be darker with such a storm brewing', '2007-07-08 16:33:36.000000', NULL, 1),
(3882422, 546780, 67553, '<td valign="top">Nice idea.  I would have rotated it CW a bit to make the sides even, though.</td>', 'Nice idea.  I would have rotated it CW a bit to make the sides even, though.', '2007-07-08 16:35:11.000000', NULL, 1),
(3882423, 547806, 74979, '<td valign="top">lovely blue, almost too much foreground for my taste w/o an "anchor" of interest for my eye.  that said, nicely done night scene.</td>', 'lovely blue, almost too much foreground for my taste w/o an "anchor" of interest for my eye.  that said, nicely done night scene.', '2007-07-08 16:35:14.000000', NULL, 1),
(3882426, 546661, 74979, '<td valign="top">mountain seems washsed out, along with the balance of the background.  A littl emore contrast would keep my interest longer I think...nice stop action on the whale..and really nice image without the bg (tighter crop).</td>', 'mountain seems washsed out, along with the balance of the background.  A littl emore contrast would keep my interest longer I think...nice stop action on the whale..and really nice image without the bg (tighter crop).', '2007-07-08 16:36:56.000000', NULL, 1),
(3882429, 548110, 67553, '<td valign="top">Good composition, but not very sharp.  The foreground seems a little out of focus.</td>', 'Good composition, but not very sharp.  The foreground seems a little out of focus.', '2007-07-08 16:37:34.000000', NULL, 1),
(3882430, 546264, 74979, '<td valign="top">oooh!  this is so lovely!  the sky is very well done &amp; I love how the sky &amp; its refelection pull me into the center of the image! bumping up..</td>', 'oooh!  this is so lovely!  the sky is very well done & I love how the sky & its refelection pull me into the center of the image! bumping up..', '2007-07-08 16:37:38.000000', NULL, 1),
(3882435, 544803, 74979, '<td valign="top">awesome light reflections on the water &amp; the tones too.  I like how though you divided the frame evenly b/tw sky &amp; water, you placed the lighthouse to the side opposite the rocks, which keep the eye moving through the image...</td>', 'awesome light reflections on the water & the tones too.  I like how though you divided the frame evenly b/tw sky & water, you placed the lighthouse to the side opposite the rocks, which keep the eye moving through the image...', '2007-07-08 16:39:37.000000', NULL, 1),
(3882442, 548050, 74979, '<td valign="top">the reflections in the water are beautiful!  It would have been interesting to see image composed of just the clouds in the water...</td>', 'the reflections in the water are beautiful!  It would have been interesting to see image composed of just the clouds in the water...', '2007-07-08 16:42:04.000000', NULL, 1),
(3882445, 548098, 67553, '<td valign="top">You have a tilted horizon.</td>', 'You have a tilted horizon.', '2007-07-08 16:42:49.000000', NULL, 1),
(3882452, 547730, 74979, '<td valign="top">I''m not a big fan of these turbines from a landscape photography perspective, particularly in a challenge named "SEA" (not WIND) :)<br/>this location is gorgeous and could have made a fabulous image of just the sky, boats, the still water, the rocks &amp; the boats.  With the clarity and lovely colors you''ve captured, this then would have felt like a far away land, from another time...</td>', 'I''m not a big fan of these turbines from a landscape photography perspective, particularly in a challenge named "SEA" (not WIND) :)this location is gorgeous and could have made a fabulous image of just the sky, boats, the still water, the rocks & the boats.  With the clarity and lovely colors you''ve captured, this then would have felt like a far away land, from another time...', '2007-07-08 16:46:48.000000', NULL, 1),
(3882458, 547912, 74979, '<td valign="top">surreal, with the tones you''ve chosen I can feel the chill; that beach is so interesting.  the black sand contrasts very well with the rest of the image.</td>', 'surreal, with the tones you''ve chosen I can feel the chill; that beach is so interesting.  the black sand contrasts very well with the rest of the image.', '2007-07-08 16:47:53.000000', NULL, 1),
(3882461, 547326, 74979, '<td valign="top">simple &amp; clean image, the lighthouse stands in perfect contrast to the rest of the image..good decision as to the time of day as you landed some very nice lighting</td>', 'simple & clean image, the lighthouse stands in perfect contrast to the rest of the image..good decision as to the time of day as you landed some very nice lighting', '2007-07-08 16:48:59.000000', NULL, 1),
(3882463, 547700, 74979, '<td valign="top">very nice!</td>', 'very nice!', '2007-07-08 16:49:26.000000', NULL, 1),
(3882466, 545616, 67553, '<td valign="top">Extra credit for the title, as it made me chuckle, but the entire image seems a bit out of focus.  I think it could use a bit more contrast between the ''rat'' and the water.</td>', 'Extra credit for the title, as it made me chuckle, but the entire image seems a bit out of focus.  I think it could use a bit more contrast between the ''rat'' and the water.', '2007-07-08 16:50:38.000000', NULL, 1),
(3882478, 547370, 67553, '<td valign="top">Very solitary sailboat.  I like the composition, but the image is a bit noisy and there is not enough detail in the sailboat.  (This looks like a crop of a full size image?)</td>', 'Very solitary sailboat.  I like the composition, but the image is a bit noisy and there is not enough detail in the sailboat.  (This looks like a crop of a full size image?)', '2007-07-08 16:54:06.000000', NULL, 1),
(3882489, 545203, 74979, '<td valign="top">I like the little sparkle of the sun glare right at the foreground..nicely done.  great image!</td>', 'I like the little sparkle of the sun glare right at the foreground..nicely done.  great image!', '2007-07-08 16:59:04.000000', NULL, 1),
(3882493, 547247, 74979, '<td valign="top">very different night capture.  love the moon in front of the cloud &amp; its reflection.  I am still trying to learn night exposures.</td>', 'very different night capture.  love the moon in front of the cloud & its reflection.  I am still trying to learn night exposures.', '2007-07-08 16:59:56.000000', NULL, 1),
(3882494, 545212, 67553, '<td valign="top">Great colors.  This is a well done shot, with the foreground and the background well exposed.  (I can never get that right in these kind of shots!)</td>', 'Great colors.  This is a well done shot, with the foreground and the background well exposed.  (I can never get that right in these kind of shots!)', '2007-07-08 17:00:04.000000', NULL, 1),
