(3882627, 547891, 74979, '<td valign="top">cool effect in those waves! great image too<br/><br/><i>Message edited by author 2007-07-13 16:29:03.</i></td>', 'cool effect in those waves! great image too', '2007-07-08 17:43:40.000000', '2007-07-13 17:29:03.000000', 1),
(3882628, 547421, 67553, '<td valign="top">This is a nice view and well processed, but I think it would have more impact if the lighthouse were more prominent.</td>', 'This is a nice view and well processed, but I think it would have more impact if the lighthouse were more prominent.', '2007-07-08 17:43:49.000000', NULL, 1),
