(3887808, 547685, 78255, '<td valign="top">Wonderful image. Where is this?</td>', 'Wonderful image. Where is this?', '2007-07-10 01:32:20.000000', NULL, 1),
(3887817, 547271, 78255, '<td valign="top">I really like this. I have a fascination for piers and bridges and this is a nice image. Strong presence of sea to fit well in the challenge with good interest in the surroundings. Good luck!</td>', 'I really like this. I have a fascination for piers and bridges and this is a nice image. Strong presence of sea to fit well in the challenge with good interest in the surroundings. Good luck!', '2007-07-10 01:34:37.000000', NULL, 1),
