(3891289, 544540, 23953, '<td valign="top">A little diffused glow in PS? nice image. good composition...the horizon could be located a little lower; it is bordering on the being located in the center third of the shot.</td>', 'A little diffused glow in PS? nice image. good composition...the horizon could be located a little lower; it is bordering on the being located in the center third of the shot.', '2007-07-11 00:32:33.000000', NULL, 1),
(3891294, 548035, 23953, '<td valign="top">Good composition, horizon is straight. Car with the breaklight has got to go. Wish the light was on in the lighthouse. Good choice of shutter speed to capture the motion of the water and not completely blur it all.</td>', 'Good composition, horizon is straight. Car with the breaklight has got to go. Wish the light was on in the lighthouse. Good choice of shutter speed to capture the motion of the water and not completely blur it all.', '2007-07-11 00:34:15.000000', NULL, 1),
