(3894133, 546802, 42013, '<td valign="top">Nice work, well captured, exposed, and composed. The lines of the rocks/water really draw me in. Congrats on top 10!</td>', 'Nice work, well captured, exposed, and composed. The lines of the rocks/water really draw me in. Congrats on top 10!', '2007-07-11 15:06:38.000000', NULL, 0),
